// Meta の response には expires_in が入らない System User の場合があるので、
// debug_token で新 token の expires_at を確認して確実な値を取る。
// 出力: { new_token, client_id_secret_app_token }
const body = $input.first().json;
if (body.error || !body.access_token) {
  throw new Error('fb_exchange_token failed: ' + JSON.stringify(body).substring(0, 500));
}
const tokenRow = $('BQ Read: Meta OAuth Token').first().json;
return [{
  json: {
    new_token: body.access_token,
    old_token: tokenRow.old_token,
    client_id: tokenRow.client_id,
    client_secret: tokenRow.client_secret,
    app_token: `${tokenRow.client_id}|${tokenRow.client_secret}`,
    // Meta の response の expires_in を fallback として保持 (System User では null が多い)
    expires_in_fallback: body.expires_in || null
  }
}];

// debug_token response から expires_at を取得し、merge_sql を組み立てる。
const debugResp = $input.first().json;
const ctx = $('Parse fb_exchange_token response').first().json;
const newToken = ctx.new_token;
const oldToken = ctx.old_token;

let expiresAtSec = null;
if (debugResp.data && debugResp.data.expires_at) {
  expiresAtSec = Number(debugResp.data.expires_at);
} else if (ctx.expires_in_fallback) {
  expiresAtSec = Math.floor(Date.now() / 1000) + Number(ctx.expires_in_fallback);
} else {
  // 情報無ければ 60 日後と仮定
  expiresAtSec = Math.floor(Date.now() / 1000) + 60 * 24 * 3600;
}
const expiresAtIso = new Date(expiresAtSec * 1000).toISOString();
const nowIso = new Date().toISOString();

const esc = (s) => String(s == null ? '' : s).replace(/\\/g, '\\\\').replace(/'/g, "\\'");

const mergeSql = `
BEGIN
  UPDATE \`campwill-ec.raw.oauth_tokens\`
  SET
    access_token   = '${esc(newToken)}',
    refresh_token  = '${esc(newToken)}',
    expires_at     = TIMESTAMP('${expiresAtIso}'),
    rotated_at     = TIMESTAMP('${nowIso}'),
    rotated_by     = 'meta-ads-token-refresh',
    refresh_count  = refresh_count + 1,
    last_error     = NULL,
    last_error_at  = NULL,
    updated_at     = TIMESTAMP('${nowIso}')
  WHERE provider = 'meta_ads';

  INSERT INTO \`campwill-ec.raw.oauth_tokens_history\`
    (provider, refresh_token, access_token, expires_at, scope, rotated_at, rotated_by, status, error_message, http_code, recorded_at)
  VALUES
    ('meta_ads', '${esc(newToken)}', '${esc(newToken)}', TIMESTAMP('${expiresAtIso}'),
     'ads_read', TIMESTAMP('${nowIso}'), 'meta-ads-token-refresh', 'success', NULL, 200, CURRENT_TIMESTAMP());
END;
`;

console.log(`Refreshed. new expires_at=${expiresAtIso}, token head=${newToken.substring(0, 15)}`);

return [{
  json: {
    status: 'success',
    new_expires_at: expiresAtIso,
    merge_sql: mergeSql
  }
}];
